def transform(grid):
    """Fill the grid with the repeating anti-diagonal color sequence."""
    h, w = len(grid), len(grid[0])
    phase = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                phase[(r + c) % 3] = value
    return [[phase[(r + c) % 3] for c in range(w)] for r in range(h)]

