 "content": "def transform(grid):
    """Fill a grid with the period-5 diagonal color pattern encoded by its clues."""
    h, w = len(grid), len(grid[0])
    phase = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                residue = (c - r) % 5
                if residue in phase and phase[residue] != value:
                    raise ValueError("inconsistent diagonal clue colors")
                phase[residue] = value
    if len(phase) != 5:
        raise ValueError("insufficient clues to determine all five phases")
    return [[phase[(c - r) % 5] for c in range(w)] for r in range(h)]
